import type { PluginOptions } from 'claude-code'

/**
 * The plugin's `userConfig`, validated: a bad value is the default (all on). `piiGuard` covers only the email refusal on `hooks_transfer`: with
 * it off, a transfer holding an email address may publish, while a secret is still refused whenever `guard` is on.
 */
export type ModOptions = { readonly guard: boolean; readonly piiGuard: boolean; readonly confirmReset: boolean }

// BEGIN SHARED FLAG (generated by scripts/sync-mod-screen.mjs; edit plugins/ruflo-agentdb/hooks/options.ts)
export const flag = (value: unknown, fallback: boolean) =>
  value === true || value === 'true' || value === 'on' ? true : value === false || value === 'false' || value === 'off' ? false : fallback
// END SHARED FLAG

export function readOptions(options: PluginOptions | undefined): ModOptions {
  const o = options ?? {}
  return { guard: flag(o.guard, true), piiGuard: flag(o.piiGuard, true), confirmReset: flag(o.confirmReset, true) }
}

export const modeOf = (o: ModOptions): Record<string, boolean> => ({ guard: o.guard, piiGuard: o.piiGuard, confirmReset: o.confirmReset })
